// Bring in Verus’s standard Prelude
use vstd::prelude::*;

verus! {

    /// Returns the index of the first occurrence of `target` in `nums`, or -1
    /// if it does not appear.  Assumes `nums.len() <= i32::MAX`.
    pub fn linear_search(nums: Vec<i32>, target: i32) -> (ret: i32)
        // precondition: length fits into i32
        requires nums.len() <= (core::i32::MAX as usize),
        // postconditions:
        ensures
            // If ret >= 0 then:
            //   1) it's in bounds,
            //   2) it is the first position where nums[..] == target,
            ret >= 0 ==> {
                let idx: usize = ret as usize;
                idx < nums.len() &&
                nums[idx] == target &&
                forall |j: usize| j < idx ==> nums[j] != target
            },
        ensures
            // If ret < 0 then target does not appear anywhere
            ret < 0 ==> forall |j: usize| j < nums.len() ==> nums[j] != target
    {
        // We reiterate the length‐bound as an assertion for use below.
        assert(nums.len() <= (core::i32::MAX as usize));

        let n: usize = nums.len();
        let mut i: usize = 0;

        // Standard loop scanning from 0 to n
        while i < n
            invariant
                // 0 <= i <= n
                i <= n,
                // All positions strictly before i have already been checked
                forall |j: usize| j < i ==> nums[j] != target
            decreases n - i
        {
            if nums[i] == target {
                // We found the first occurrence
                return i as i32;
            }
            i += 1;
        }

        // Not found
        -1
    }

}